INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Коркарони розмарин — наъбекии дорушӣ ва хушбӯи маъмул — ҳассосияти махсуси коҳишпаздории манбаъҳои об дорад. Дар шароити имрӯза, ки хароҷоти истеҳсол афзуда ва манбаъҳои об маҳдудтар шудаанд, истифодаи системаҳои нави ороғ, ба монанди ноҳои дроббӣ (капплӣ), аз интихоби ихтиёрӣ ба зарурат табдил ёфтааст. Аммо бисёри деҳқонҳо ва боғбонҳо ба як мушкили асосӣ дучор меоянд: чӣ тавр дар бораи саломатии ноҳои дроббӣ дақиқ ҳисоб кунанд ва ин системаро чӣ гуна идора намоянд, то ҳам решаҳои нозуки розмарин ҳифз карда шавад ва ҳам тӯли умри фойдавии лавозимот нигоҳ дошта шавад? Дар ин мақола, ҳамчун як роҳнамои амалӣ, мо ба баррасии нуқтаҳои муҳим дар <strong>нигоҳдории розмарин бо ноҳои дроббӣ</strong> мебахшем, то шумо аз нақси қатъ ва меҳнати худ беҳтарин фоидаро бароред. Ин роҳнамо на танҳо ба принсипҳои техникии ороғи қатрагӣ даънат мекунад, балки ба таъсир ба шакли гиёҳи розмарин дар ҷавоб ба тағйирёбии рутубат ҳам таваҷҷуҳ медиҳад.</p>\n\n<h2>Аҳамияти ноҳои дроббӣ дар идоракунии рутубати розмарин</h2>\n<p>Розмарин гиёҳест, ки решаҳои он ба чуқурӣ мераванд, аммо системаи решагии он ба тағйирёти ғайриинтизории рутубат ҳассос аст. Ноҳои дроббӣ бо партобдани об ба таври якхела ва мустақиман ба минтақаи реша, шоки рутубатиро ба ҳадди ақал мерасонад. Баръакси ороғи пахшкунанда, ноҳои дроббӣ имкон медиҳад, ки сатҳи хок дар атрофи решаҳо хушктар бомад, ки ин коркарди кӯфти решагӣ ва ризинг-ро кам менамояд. Бо вуҷуди ин, муваффақияти ин система ба интихоби дурусти навъи ноҳо ва танзими дақиқи фишор вобаста аст. Агар шумо хоҳед, принсипҳои интихоби навъи мувофиқро донед, метавонед мақолаи <a href="https://navar-abyari.ir/how-to-choose-suitable-drip-irrigation-tape/">how to choose suitable drip irrigation tape</a> ро омӯзед, то аз меъёри техникии интихоби беҳтарин модел барои розмарин огоҳ нашавед.</p>\n\n\n\n<h2>Оғози дуруст: омодагӣ аз замин ва коркард</h2>\n<p>Қаблан чигоридан пеш аз насб кардани системаи лентаи қатра, тайёрӣ намудани замин нақши муайянкунанда дорад. Розмарин хокҳои нозукшавандаро маъқул дорад. Хокҳои вазнин ва лаҳмаргҳо метавонанд боиси сипа шудани зуд сӯрохҳои лента шаванд. Ҳамкорӣ мешавад, ки пеш аз намон, хок куфта ва бо чипка шуста шавад, то барои ҳавогирии мувофиқ кафолат дода шавад. Масофа байни қаторҳои розмарин низ бояд дар асоси модели лента танзим карда шавад. Одатан лентаро дар миёнаи масофаи қаторҳо ё дар қаторҳои зира насб мекунанд. Нуқтаи асосӣ дар ин марҳила, намондани растаниҳои розмарин бо масофаи муносиб аз ҷойдубор асосӣ аст, то дар вақти осорӣ хок зери лента зиёда нарм нашавад ва решаҳо зада нашаванд. Инчунин, истифодаи филтра мувофиқ дар ҷодахӯрии система аз рӯзи аввал зарур аст, то зарраҳои суқуткунандаи об ворид шудан ба лентаи қатраро пешгирӣ кунад.</p>\n\n<h2>Нуқтаҳои тахассусии хатоёбӣ ва нигоҳубини рӯзмарра</h2>\n<p>Тозагӣ ва устувории лентаи қатра ба нигоҳубини рӯзмарра вобаста аст. Яке аз мушкилоти бешумора, суст ё қатъ шудани ҷараёни об дар каъиндҳои мушаххаси лента аст. Ин метавонад ба сабаби ворид шудани зарраҳои хок, рушди мемҳои микробии дохилии лента ё зарардиҳии лента аз ҷониби ҳайвонот бошад. Барои пешгирӣ, бояд аз ҳавогираҳои мувофиқ истифода баред, то ҳавои маҳбус шуда, боиси пар шудани лентаҳои сабук вазн нагударад. Инчунин, назорати давравии фишори об дар нӯхи кӯлҳо муҳим аст; паст шудани фишор аз ҳад зиёд метавонад аломати сипа шудан бошад. Барои шиносоӣ бо марҳилаҳои тахассусии нигоҳубин, метавонед ба раҳнамоии нигоҳубини лентаи қатра ва ҳаҷми он муроҷиат намоед, ки муҳимтарҳои таъмироти пешгиронаро эътироф мекунад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-رزماری-با-نوار-تیپ-نکات-کلیدی-تصویر-شاخص.webp" alt="نگهداری رزماری با نوار تیپ: نکات کلیدی - تصویر 1"/><figcaption>crop drip tape maintenance care розмарин</figcaption></figure>\n\n<ul>\n<li><strong>Ҷӯш (шустани) мунтазам:</strong> Ҳар 1 то 2 моҳ як бор, системаро бо оби фишори баландтар аз меъёри оддӣ шуста бошед, то ҷамъшавиҳо аз дохили lenta хориҷ шаванд.</li>\n<li><strong>Нигоҳубини филтрҳо:</strong> Тоза кардани филтрҳо бояд ҳар ҳафта ва ё пас аз ҳар як истифода иҷро шавад. Филтри оббӯда душмени асосии лентаи қатра аст.</li>\n<li><strong>Хол кардани партофлурети бар:</strong> Барҳои нарми дар обҳавии шамолнокӣ ва ҳангоми ҳаракати асбобҳои кишоварзӣ зарар мебинанд. истифодаи симҳои мустаҳкамкунанда ё хокӣ дар зери бар тавсия дода мешавад.</li>\n</ul>\n\n<h2>Барномасозии обкорӣ: аз миқдор то сифат</h2>\n<p>Миқдор ва вақти обкории рузмарин бо барҳои нарм бояд вобаста ба шартҳои обҳавии минтақа танзим карда шавад. Дар рӯзҳои гармтарин, обкориҳои такроршаванда бо ҳаҷми камтар беҳтар аз обкориҳои кам ва беш аз ҳад мебошад. Рузмарин барои обкории аз боло (обкории пашавӣ) ҳассос аст, зеро боиси бемориҳои сафедагӣ баргҳо мешавад. Барҳои нарм дақиқ ин мушкилро ҳал мекунанд. Ҷадвали зерин пешниҳод барои тақсимот тахминии обкорӣ вобаста ба фасл аст, ки бояд бо фикри ихтисосдони маҳаллӣ мутобиқ шавад:</p>\n\n<table>\n  <thead>\n    <tr>\n      <th>Фасл</th>\n      <th>Шумораи обкориҳо дар ҳафта</th>\n      <th>Ҳудуди дарозии обкорӣ (дақиқа)</th>\n      <th>Нуқтаҳои калидӣ</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <td>Баҳор</td>\n      <td>2 то 3</td>\n      <td>20 то 30</td>\n      <td>Зиёд кардани обёрӣ бо сабзидаҳои нав; назорати алафҳо.</td>\n    </tr>\n    <tr>\n      <td>Тобистон</td>\n      <td>4 то 5</td>\n      <td>15 то 25</td>\n      <td>Обёрӣ дар соатҳои хунук (соҳаи бегоҳ ё оҳанг) барои камак кардани бухоршавӣ; назорати дақиқи фишор.</td>\n    </tr>\n    <tr>\n      <td>Пазир</td>\n      <td>1 то 2</td>\n      <td>20 то 30</td>\n      <td>Танзими тадриҷии оборӣ барои омода кардани ниҳол ба хоби тирамоҳ; тоза кардани пурраи об аз лӯлаҳо дар минтақаҳои хунук.</td>\n    </tr>\n    <tr>\n      <td>Зимистон</td>\n      <td>0 то 1</td>\n      <td>—</td>\n      <td>Оборӣ танҳо дар сурати хушкшавии нозуккунии хок; муҳофизат кардани наҳоридӣ дар баробари яхбандӣ.</td>\n    </tr>\n  </tbody>\n</table>\n\n\n\n<p>Қайд кардан мумкин аст, ки рамсӣ ба ҳисоби ҳайвоноти хушкӣ дӯстдор ҳисобида мешавад ва обори иловагӣ метавонад ба чӯр шудани реша ва дарёи ниҳол оварда расонад. Бинобар ин, истифодаи сенсорҳо дар ғайринормалии хок ё ҳатто тамошои бинарӣ бо фрекенсияи мунтазам беҳтар аз итмом додани вақти кор аст.</p>\n\n<h2>Навбатии обороги вағизокунии парҳезӣ (фурӯрӣ)</h2>\n<p>Яке аз имтиёзҳои асосии нӯри тупӣ имконияти фурӯрӣ (паҳн кардани моддаҳои ғизоӣ бо об) аст. Розмарин дар фаслҳои рӯиш ба нитроген ва дар фаслҳои гулбаст ва меварезӣ ба калий ва калсий ниёз дорад. Бо пайваст кардани як қатраандози ё валифити мувофиқ ба вурудии система, шумо метавонед моддаҳои минералӣ-ро бевосита ба минтақаи решаҳо барсояд. Ин усул ба эҷоди хароҷот барои аҳром ва зиёдшавии ҷабҳи моддаҳои ғизоӣ тарафи растанӣ мусоидат мекунад. Албатта бояд диққат дод, ки аз омехта намудани моддаҳои номувофиқ (мисол калсий бо фосфор), ки боиси омадани ҳалшудагиҳо ва дағалкунии лӯлаҳо мешавад, дурӣ доред. Инчунин, дар сурати истифода аз ноғирҳои боздоранда, исбот кунед, ки pH-и об дар доираи мувофиқ аст, то аз омадани чорикҳо дохили сӯрохҳои нӯр пешгирӣ шавад.</p>\n\n<h2>Пешгирӣ аз дағалкуиҳои кимиёвӣ ва биологӣ</h2>\n<p>Дағалкӣ яке аз душманони асосии нӯри тупӣ аст. Дағалкуиҳои биологӣ ба рӯшӣи бактерияҳо ва алакро дар дохили об оварда мерасонанд, ки метавонанд сӯрохҳои нӯро пӯшонанд. Истифодаи мунтазами дезинфектаторҳои кимиёвӣ (монанди хлор) дар миқдори иҷозатшуда ба пешгирӣ аз ин мушкилот мусоидат мекунад. Аз тарафи дигар, дағалкуиҳои минералӣ аз ҳалшудагиҳои намакҳо (монанди калсий ва магний) бармеояд. Агар оби минтақаи шумо сахт бошад, бояд аз кислотаҳои бехатар (монанди кислотаи sitrik) барои кислотакунии об бисёр истифода баред, то аз таъсири чорикҳо пешгирӣ шавад. Он гуна корро бе мушокират бо ихтисоси обшиносӣ қатъан иҷро накунед, зеро кислотаҳои номувофиқ метавонанд ба пайкасти нӯр зарар расонанд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-رزماری-با-نوار-تیپ-نکات-کلیدی-کاربرد-عملی.webp" alt="نگهداری رزماری با نوار تیپ: نکات کلیدی - تصویر 2"/><figcaption> crop drip tape maintenance care Розмарин</figcaption></figure>\n\n<h2>Назоратҳои даҳшавона ва муоинаҳои фаслӣ</h2>\n<p>Нигоҳубинии резмарӣ бо напҳоҳои дурӯбӣ маънои инро надорад, ки кори якбораи аст, балки раванди доимӣ мебошад. Дар оғози ҳар мавсим тамоми роҳи напҳоро бо чашмӣ чинед. Ҷустуҷӯ кунед, ки қамаҳо, дарахташҳо ё чалупҳои хурд дар ҷое, ки об аз онҳо берун меояд, мавҷуд бошанд. Напҳоҳои қадимаи дурӯбӣ хосияти эластикӣ-и худро аз даст медиҳанд ва ҷорик мешаванд. Додарин ҳолатҳо иваз кардани напҳоро беҳтар аз таъмир аст. Ҳамчунин, ширҳои пайвастшавии напҳо бо фитингҳоро санҷед; шаббудани пайвастаҳо яке аз сабабҳои асосии коҳиши фишор дар оғози напҳо мебошад. Агар дар муқобила бо мушкилоти мушаххас дар насб ё интихоби қисмҳо рӯбарӯ шудед, омехтани мақола <a href="https://navar-abyari.ir/%D8%A7%D9%86%D8%AF%D8%A7%D8%B2%D9%87%DA%AF%DB%8C%D8%B1%DB%8C-%D9%81%D8%B4%D8%A7%D8%B1-%D8%A2%D8%A8-%D8%A8%D8%B1%D8%A7%DB%8C-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE/">Андозагирӣ фишори оби напҳои дурӯбӣ</a> мебошад, ки роҳнамои хуб барои танзими механикӣ аст.</p>\n\n\n\n<h2>Саволҳои маъмул (FAQ)</h2>\n\n<h3>Оё имкон аст, ки напҳои дурӯбӣ барои резмарӣ дар ҳамаи шароити иқлимӣ истифода шаванд?</h3>\n<p>Бале, напҳои дурӯбӣ яке аз системаҳои сермӯҳлаттарин аст. Дар минтақаҳои хушк, он боиси кам шудани таҳриҳо ва истифодаи муътадили об мебошад. Дар минтақаҳои намнок, ба пешгирии зиёди об дар решаҳо ва бемориҳои реша кӯмак мекунад. Ягона фарқият дар нақшаи вақтӣи обёрӣ аст.</p>\n\n<h3>Агар напҳои дурӯбӣ дар соати аввали кор кардан хомӯш шаванд, чӣ гуна ҳал мекун?</h3>\n<p>Аввал, филтрҳоро санҷед ва тоза кунед. Дуюм, вориди напҳоро аз шир асосӣ ҷудо кунед ва онро ба ширҳои шаҳрвӣ ё системаи дигар пайваст кунед ва бо фишори баланд шустарӣ кунед, то нимваҳшавандаҳо боз шаванд. Агар мушкил иссӣ бошад, эҳтимол вориди напҳо осеб дорад ва лозим ба иваз кардан аст.</p>\n\n<h3>Оё рюкзак (nibaribor) барои истифодаи дубора барои бардошти минбаъда имконпазир аст?</h3>\n<p>Одатан, рюкзакҳои сабук (Single-wall) як бор истифода мешаванд. Рюкзакҳои мустаҳкамтар (Double-wall) то 3 то 4 фасл қобили истифодаи дубора мебошанд. Барои розмарин, ки дарахти бисёрсола аст, истифодаи рюкзакҳои мустаҳкамтар тавсия меёбад. Пеш аз насб дар фасли нав, рюкзакро пурра шуста бароред.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/نگهداری-رزماری-با-نوار-تیپ-نکات-کلیدی-جزئیات-فنی.webp" alt="نگهداری رزماری با نوار تیپ: نکات کلیدی - تصویر 3"/><figcaption>нигоҳубини ва парвариши рюкзак барои бардошт розмарин</figcaption></figure>\n\n<h3>Беҳтарин вақт барои иваз кардани рюкзакҳои фарсода чист?</h3>\n<p>Агар дида бароед, ки омодагии об аз рюкзак баробар набошад, ё шикастҳои зиёд дошта бошад ва ислоҳи он аз рӯи иқтисодӣ қобили қабул набошад, вақти ивазрасидан расидааст. Одатан, дар охирин дараҷаи парвариши розмарин (пеш аз кӯҳандонии бардошти нав) беҳтарин вақт аст.</p>\n\n<h2>Хулоса ва тавсияи ниҳоӣ</h2>\n<p>Истифодаи рюкзак барои <strong>нигоҳубун ва дористории розмарин</strong> Ин сармоягузории ҳосилнокун барои беҳтар намудани самаранокӣ ва коҳиш додани истеъмоли об аст. Дар ҳоле ки мадорҳои техникии худро дида нарасед; тозагии филтрҳо, таҳқиқи мунтазами норасониҳо ва нақшагузории дурусти обёрӣ, пойгираи асосии бартарист. Бо риоя намудани оғузи овардашуда, метавонед набототи сафед ва хайли дорудаори рамсиро дар тӯли сол истифода баред. Ядгор доред, ки ҳар як замина шартҳои худгоҳӣ дорад, бинобар ҳамеша аз таҷриба оморӣ истифода баред ва вобаста ба ҷавоби наботот, танзимоти худро ислоҳ кунед. Барои даидиши мавзӯи пайваста бо низоми истеҳсоли ғайри инҳо ва оғузи иловагӣ, шумо метавонед ба мақолаи дар поён нишон додани обёрӣ низ ошӣ бигиред, ки нуқтаи назари пуркунанда ба обёрии рамсиро пешниҳод мекунад.</p>\n<p><strong>Маҳсулотҳои пайваста:</strong> <a href="https://navar-abyari.ir/%d9%85%db%8c%d8%b2%d8%a7%d9%86-%d8%a8%d8%b1%d8%af%d8%a7%d8%b4%d8%aa-%d8%aa%d8%b1%d8%a8-%d8%b3%db%8c%d8%a7%d9%87-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори кам кардани торби сиёҳ дар ҳектаор + омилҳои таъсиррасон</a>، <a href="https://navar-abyari.ir/triticale-seed-per-hectare-density-table/">triticale seed per hectare density table</a></p>','Тарҳовии ризони бо навори T: Нуктаҳои асосӣ барои обёрӣи муҳим','Дар ин мақола, мо ба омӯзиши тафсӣ нигоҳдошти розмарин бо истифода аз системаи нӯри тайп мепардозем. Бо донистани нуқтаҳои калидӣ дар интихоб, насб ва хатоёфти нӯри тайп, шумо метавонед аз стресс обии розмарин пешгирӣ кунед ва сифати маҳсули худро дар фаввараҳои гуногун баланд бардоред. Дар ин роҳнамо ҳалли амалӣ барои идоракунии фишор ва пешгирии гиреҳи лӯлаҳо пешниҳод шудааст.','publish','closed','closed','targhobii-rizoni-bo-navari-t-obori-muhim',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
