INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Розмари (<em>Salvia rosmarinus</em>) яке аз ҳабиҳо ва ҳабиҳои модарӣи машҳур дар ҳосилкории саноатӣ ва хонагӣ мебошад, ки ба сабаби хушбӯӣ ва таъмидеги ва хосусиятҳои доруии бисёрона, ҷойи махсусро дар бозорҳои бардошт дорад. Азбаски розмари ҳаби нимбиёбонӣ аст, он ба хушкӣ муқобилат мекунад, аммо обёривии номувофиқ метавонад мувозинати биологии ҳабро вайрон софта, онро барои гирифтан ба бемориҳо ва ҳашархӯрӣ осони кунад. Дар солҳои охир системаҳои обёривии қатраӣ ва нӯраи таҳтӣ ҳамчун ҳалҳои беҳтарин дар кишоварии муосир шинохта шудаанд. Ин системаҳо бо кам кардани намии сатҳӣ ва назорати дақиқи миқдори об нақши муҳимро дар пешгирии бемориҳои заминӣ ва пардозани баргҳо иҷро мекунанд. Аммо оё обёривии қатраӣ алоҳида метавонад ҷойи ҳамаи идоракунии бемаҳролро ишғол кунад? Дар поён, тафсилоти фаннӣ ва амалӣ дар бораи алоқамандии байни обёривии розмари ва идоракунии ҳашарот ва бемориҳоро баррасӣ мекунем.</p>\n<h2>Таъсири обёривии қатраӣ бар устувории экосистемаи розмари</h2>\n<p>Муҳимтарин афзалияти обёривии қатраӣ дар ҳосилкории розмари, марказӣ гардондани намӣ дар минтақаи рӯн (наҳӯр-рӯнӣ) ва хушк нигоҳ доштани сатҳи замин аст. Бисёр бемориҳои қамунҳои розмари, ба махсус гирд кардани рӯн ва пессил, дар шартҳои замини намнок ва сард, суръати афзоишашон баландтар аст. Бо истифода аз нӯраи таҳтӣ, намӣ бевосита ба рӯнҳо ворид карда мешавад ва сатҳи замин, ки ҷойи фаъолияти спораҳои қамунҳо ва зараррасон аст, хушк боқӣ мемонад. Ин раванд вақти афзоиши спораҳо ва популятсияи ибтидоии зараррасонҳоро таъхир медиҳад.</p>\n<h3>Нақши обёривии нӯраи таҳтӣ дар кам кардани гирд кардани рӯн</h3>\n<p>Гирд кардани рӯн, яке аз таҳдидҳои бадкунанда барои розмари аст. Обёривии обдор (ғарғарӣ) ё боронкашӣ, ки боиси мондани оби иловагӣ дар атрофи кобук ва рӯнҳо мегардад, муҳити идеалӣ барои қамунҳои <em>Phytophthora</em> ва <em>Fusarium</em> роҳ фароҳам меорад. Баръакс, системаи навори пичоқ (drip) бо фосиларо мувофиқ, имкон медиҳад, ки оксигенрасонӣ ба решаҳо нигоҳ дошта шавад. Тавсия мешавад, ки дар тарҳрезии система навори пичоқ ба таври чунин ҷойгир карда шавад, ки аз нам шудани бевосита пояҳои поёнии растани пешгирӣ кунад, зеро ин қисматҳо ҳангози нам мондан бодиққаттараз бемориҳои бактериявӣ ва зангӣ гирифта нигардад.</p>\n<p></p>\n<h2>Муҳимтарин зараррасонандагон ва бемориҳои розмарин ва тарзи таъсиригорӣ бо онҳо ва обёрӣ</h2>\n<p>Шинохти зараррасонандагон ва бемориҳои ҳадаф, пешнудҳои тарҳрезии дурусти системаи обёрӣ мебошад. Розмарин бештар аз зараррасонандагони фистову маҳмакҳо ва мҳаки сафед таъсир мекунад, ки бо идоракунии обёрӣ робитаи бевосита надоранд, аммо бемориҳо ва ҳашароти хокзистан бештарин вобастагӣ ба намнокӣ доранд.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-رزماری-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های رزماری با آبیاری قطره‌ای - تصویر 1"/><figcaption>zararрасонагони ҳашароти бемориҳои обёрии пичоқ розмарин</figcaption></figure>\n<h3>Маҳмаки сафед ва зараррасонандагони розмарин</h3>\n<p>Зараррасонандагони розмарин (<em>Sparganothis bithynicella</em>) яке аз асоситарин зараррасонандагони ларвиҳои ин растани аст, ки решаҳо ва пояҳоро мехӯрад. Мавҷудияти намноки зиёд дар минтақаи реша, бо сабаби кам шудани муқовимати растани ба стресс, ларвиҳоро ба кишт мекашад. Обёрии дақиқи пичоқӣ метавонад стресси растаниро коҳиш диҳад; зеро растани солим ва бо таносуби мувофиқ (таркиби об ва микроғизо) системои иммунитети қавитартарро бар зидди ҳамлаи ҳашарот дорад. Аз сӯи дигар, маҳмакҳои сафед барои ҳастии умри бандгонӣ ба намноки баланд вобастаанд. Бо хушк нигоҳ доштани сатҳи хок тавассути навори пичоқ, шумораи маҳмакҳои сафед ба таври табиӣ кам мегардад.</p>\n<h3>Зараррасонандагони беморӣ ва парҳези баргҳо</h3>\n<p>Кошиҳои қарачеҳ, ки дар шакли дағдаҳои зард ва бунавҷотӣ бар баргҳо пайдо мешаванд, бевосита бо пур кардани баргҳо бо равони об алоқаманданд. Дар системаҳои оборӣи қатрагир, азбаски об аз қатрагирҳо дар баландии паст ё болои замин рёфта мешавад, эҳтимоли пур шудани баргҳо ба таври назаррас кам мешавад. Ин нуқта барои боғбонии шӯрбо, ки барги барак ва бо муҳафизати воскӣ дорад ва барои тарк кардани ҳарорати муҳити баланд ҳаракат мекунад, хеле муҳим аст.</p>\n<p></p>\n<h2>Нуқтаҳои амалӣ дар нақшаи системаи оборӣ барои боғбонии шӯрбо</h2>\n<p>Барои фоида бурдан аз ҳамаи манофети пешгирии оборӣи қатрагирӣ дар боғбонии шӯрбо, бояд нуқтаҳои зерин дар нақшаи система ба назар гирифта шаванд:</p>\n<ul>\n<li><strong>Интихоби қатрагирҳо:</strong> Барои шӯрбо қатрагирҳои бо сарпайи паст (масалан, 1 ё 2 литр дар як соат) истифода баред. Ин наботот ба оборӣи мубтало ва камҳаҷм мебошад.</li>\n<li><strong>Фавари қатрагирҳо:</strong> Фавари қатрагирҳо бояд мувофиқ бо баландии наботот дар солҳои аввал ва дуюм танзим шавад. Бо афзоиши шӯрбо ба баландии баландтар, даираи қабули марғуборӣ низ васеъ мешавад.</li>\n<li><strong>Оборӣ зерозӣ (Sub-drip):</strong> Дар баъзе системаҳои пешрафта, аз ҷабҳои зерзаминӣ барои инъикоси оби амиқ истифода мешавад, тонамъмоисиҳои рӯи намоӣ ба ҳадди ақалл бардоранд. Ин роҳ беҳтарин ҳолат барои пешгирии бемориҳои зарға-ҳавии рӯи намоӣ мебошад.</li>\n<li><strong>Поливҳои маҳлулпашки решаҳо:</strong> Аз нуби дрип барои инъикоси гуногунии ва баъзе заҳрушавии системӣ истифода баред. Ин кор мувофиқати маводди мӯъсиро мустақиман ба зонаи ҷазоби реша мебардорад.</li>\n</ul>\n<p>Инчунин, диққат ба масофаҳои кӯрӣ муҳим аст. Барои оиди стандартҳои оптималӣ аз масофагузорӣ дар парвариши гиёҳҳои мӯчҷии, шумо метавонед дастури комил аз нуби дрипро омӯзед, ки принсипҳои умумии ҷойгиркунии хатҳоро мефаҳмонад. Дар парвариши розмарин, зичии зиёд ба зиёдшавии намдории нисбӣ дар дохили саҳҳо ва натиҷаман бари зарғаҳо боис мешавад. Аз ин рӯ, фазои кофӣ байни қаторҳо барои ҳавопакиши мувофиқ, аз афзалиятҳои тарҳи дуруст мебошад.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-رزماری-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های رزماری با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation розмарин</figcaption></figure>\n<h2>Идоракунии якҷояи заҳрушавӣ (IPM) дар паҳлӯи обёрӣ-нубӣ</h2>\n<p>Обёрӣ-нубӣ қисме аз стратегияи калонтаре бо номи идоракунии якҷояи заҳрушавӣ мебошад. Ин система худаш заҳрушавиро нест намекунед, вале бо кам кардани шиддат бар гиёҳҳо ва маҳдуд кардани манбаъҳои мувофиқ барои ҳашарот, ниҳод ба заҳрушавии ҳашаротро ба охир мекашад.</p>\n<h3>Назорати мунтазам ва намунагирӣ</h3>\n<ol>\n<li>Ҳарфи як-бар, риштаҳои гармшударо бо готик санҷед.</li>\n<li>Баргҳои поёнии розмариаро барои мавҷудияти дағалҳои зард ё ҳашароти часпандагӣ (асал) санҷед.</li>\n<li>Агар шумо барои татуо аз тулаҳои люкиндор истифода мебард, шумораи намунаҳоро бо граффик сабт кунед.</li>\n</ol>\n<p>Агар сатҳи намии хок бо пикометр санҷида шавад, метавон аз обёрии иловагӣ, ки сабаби фусух аст, пешгирӣ кард. Дар ин соҳа, даромадани принсипҳои асосии обёрӣ ва робитаи он бо саломати наботот зарур аст. Барои шиносӣ бо принсипҳои умумии чӣ тавр набототи доруии монандро парвариш кардан, метавонед ба <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%b2%db%8c%d8%b1%d9%87-%d8%b3%d8%a8%d8%b2-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">мақолаи миқдори бодаи зиреи сабз дар гектар</a> нигаред; зеро зиреи сабз низ монанди розмари, набототи заминаи миёназаминӣ бо зарурати обёрӣи монанд аст.</p>\n<p></p>\n<h2>Ҷавоб ба саволҳои оддӣ</h2>\n<h3>Оё обёрӣи тамчина метавонад ивази заҳролукшии муқобила ба қамарбонон бошад?</h3>\n<p>Не. Қатқомагӣи заррадорӣ як воситаи пешгиристӣ аст, на даво. Агар бемории қуфунӣ муайян карда шуда бошад, бояд аз воситаҳои занбӯрунқатликунандаи кимиёвӣ ё биологӣ (масалан, <em>Trichoderma</em>) истифода баред. Қатқомагӣи заррадорӣ танҳо аз такрор ва паҳншавии беморӣ пешгирӣ мекунад.</p>\n<h3>Беҳтарин вақти қатқомагии заррадории розмарин дар кадом ҳолат аст?</h3>\n<p>Маслиҳат дода мешавад, ки қатқомагиро субҳи бешом ё охири шом анҷом диҳед, то табухшавӣ ба ҳадди ақалл расонад. Аммо, дар тизими қатқомагии заррадорӣ, вақти қатқомагӣ аҳамияти камтар дорад, зеро об бевосита ба реша мерасад. Муҳимтарин принсип, аз қатқомагии дарозмуддат дар шаб, ки боиси пусидан мегардад, худдорӣ кардан аст.</p>\n<figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-رزماری-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های رزماری با آبیاری قطره‌ای - تصویر 3"/><figcaption>crop pests diseases drip irrigation розмарин</figcaption></figure>\n<h3>Оё масоҳати ришаи қатқомагӣ барои розмарин бо дигар дарахтони ордӣ якхела аст?</h3>\n<p>Не. Муайян кардани масоҳат бояд дар асоси чуқурии реша ва даири тӯлӯи дарахт танзим карда шавад. Барои огоҳӣ дар бораи принсипҳои муайян кардани масоҳат дар дигар дарахтон, шумо метавонед роҳнамоии муайян кардани масоҳати қатқомагиро барои лобӯро омӯзед, ки принсипҳои муайян кардани масоҳатро дар асоси андозаҳои дарахт шарҳ медиҳад.</p>\n<h3>Оё розмарин ба ҳашаркӯбӣ дар решаҳо ниёз дорад?</h3>\n<p>Бале, ризомана ба озод ва фосфери миёна ниёз дорад, аммо ба потассий ҳассос аст. Инъексияи маҳлулҳои ҳушандор тавассути рӯibar тик (обкории фитовия) усули бисёр самаранокист, ки дар он моддаҳои ғизоӣ ба таври мустақим ба решаҳои фаъол мерасанд.</p>\n<h2>Хулоса ва тавсияҳои охирин</h2>\n<p>Истифодаи обкории қатқатӣ дар ҷуғурди ризоҷи, на танҳо барои сарфаи об, балки стратегияи мудофиаи қавӣ зидди бемориҳои хокӣ ва зараррасонҳост. Бо интихоби қатқаткашони мувофиқ, танзими масофаҳо ва назорати доимӣ, шумо метавонед шумораи зараррасонҳоро кам намоед ва маҳсулоти сифатдор ва камнуқсол ҳосил кунед. Агар дар тарҳрезии системаи обкории майдони ризоҷи савол дошта бошед ё ба маслиҳат дар бораи андозабандии лӯлаҳо ниёз доред, таҳияи мақолаҳои ихтисосии бештар дар бораи <a href="https://navar-abyari.ir/lif-flat-pipe-price-guide-tajikistan/">рубари лӯлаи тик</a> метавонад ба шумо дар интихоби ҷинс ва қубури лӯлаи мувофиқ кӯмак расонад. Дар охир, дар ёди шумон бошад, ки кӯлаки ризоҷи солим, ки аз стресси об азия намекунад, беҳтарин мудофиаи зидди зараррасонҳо аст.</p>\n<p><strong>Маводи алоқаманд:</strong> <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%d8%a7%d8%b3%d9%81%d9%86%d8%a7%d8%ac-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Миқдори бисори шпинат дар гектар + омили таъсиррасон ва усулҳои афзоиш</a>, <a href="https://navar-abyari.ir/%d9%85%d9%82%d8%af%d8%a7%d8%b1-%d8%a8%d8%b0%d8%b1-%da%a9%d8%a7%d9%87%d9%88-%d8%af%d8%b1-%d9%87%da%a9%d8%aa%d8%a7%d8%b1/">Муқаддари бехи салолӣ дар гектар + нуқтаҳои кайи ва обёрӣ</a></p>','Шароратҳо ва бемориҳои розмарин тавассути системаи обёркунии қатқата: тавсияҳои идоракунӣ ва пешгирии онҳо','Розмарин гиёҳи ба камобии об тобовар аст, аммо обёрди нодуруст метавонад заминаи бемориҳои қофзӣ ва ҳамлаи зарароваронро фароҳам орад. Дар ин мақола нақши обёрдии таҳқирӣ ва шитоби хатӣ дар идоракунии кишоварзии розмарин баррасӣ шудааст.','publish','closed','closed','afvat-va-bemorihoi-rozmarin-oborkunii-qattati',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
