INSERT INTO `ha_postmeta` (`post_id`,`meta_key`,`meta_value`) SELECT @translation_id,'_rank_math_description','Оҳанҳои муҳим дар бораи шароратҳо ва бемориҳои розмарин дар тавсифи системаи обёркунии қатқатӣ бо истифодаи қатқати муҳол, пешгирии бадкорандаҳо, ва бозхонии қабати гулбаргор. Тавсияҳои пурра барои фаъолияти қуттии қуттӣ.' WHERE @translation_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `ha_postmeta` WHERE post_id=@translation_id AND meta_key='_rank_math_description');
